{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "isOpen",
      "type": "boolean",
      "description": "Whether the lightbox is open.",
      "required": true
    },
    {
      "name": "onOpenChange",
      "type": "(isOpen: boolean) => void",
      "description": "Callback when the lightbox open state changes: the Close button, Escape, a tap beside the media, or, on a phone or tablet, dragging a photo down from its fitted size.",
      "required": true
    },
    {
      "name": "media",
      "type": "LightboxMedia | LightboxMedia[]",
      "description": "Media to display. Pass a single object for one item, or an array for gallery mode with prev/next navigation (on a phone or tablet, a swipe moves between items too). Each item is {src: string, alt: string, caption?: ReactNode, type?: 'image' | 'video'}; type defaults to 'image', and zoom/pan is disabled for 'video'.",
      "required": true
    },
    {
      "name": "index",
      "type": "number",
      "description": "Current index in gallery mode (when media is an array)."
    },
    {
      "name": "onIndexChange",
      "type": "(index: number) => void",
      "description": "Callback when the gallery index changes: prev/next, the arrow keys, or a swipe."
    },
    {
      "name": "hasZoom",
      "type": "boolean",
      "description": "Enable zoom (images only): pinch (or ctrl-wheel), or double-tap or double-click to zoom in at that point and back; Enter/Space/+/- zoom 2× about the centre and back, and 0 returns to the fitted size. When zoomed, drag or scroll a trackpad to pan, or use arrow keys; on a phone or a tablet, the pan has momentum.",
      "default": "false"
    },
    {
      "name": "defaultIndex",
      "type": "number",
      "description": "Initial image index in gallery mode for uncontrolled usage.",
      "default": "0"
    },
    {
      "name": "hasAutoPlay",
      "type": "boolean",
      "description": "Automatically start video playback when a video media item is shown.",
      "default": "false"
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization. Must be stylex.create() value."
    }
  ],
  "meta": {
